# Auto-generated by refactor: extracted verbatim from starter.py (factory + blueprints split).
from flask import (Blueprint, abort, current_app, jsonify, redirect,
                   render_template, request, session, url_for)
from flask_login import login_required, login_user, logout_user
from flask_limiter.util import get_remote_address
from werkzeug.security import check_password_hash

from app.config import COGNITO_ENABLED, COGNITO_HOSTED_DOMAIN, COGNITO_APP_CLIENT_ID
from app.extensions import db, limiter, oauth
from app.models import User
from app.services.cognito import CognitoLinkError, get_or_create_user
from app.services.gamification import complete_quest_for_user
from app.services.referral import consume_referral, ensure_referral_code
from app.services.validators import _DUMMY_PW_HASH, validate_email, validate_password, validate_username


bp = Blueprint("auth", __name__)

# /login?err=<code> → kullanıcıya gösterilecek Türkçe mesaj (Cognito geri dönüş
# hatalarını güvenli, sabit bir kümeyle eşler; ham hata sızdırılmaz).
_AUTH_ERRORS = {
    "cognito": "E-posta ile giriş tamamlanamadı. Lütfen tekrar deneyin.",
    "link": "Bu e-posta zaten kayıtlı. Kullanıcı adı/şifre ile giriş yap ya da "
            "Cognito'da e-postanı doğrulayıp tekrar dene.",
}


def _cognito_available():
    return COGNITO_ENABLED and oauth is not None


def _login_username_key():
    """Per-account login rate-limit key: the submitted username (lowercased).

    The default login limit is keyed by client IP, which does not throttle a
    *distributed* brute force that spreads guesses for one account across many
    IPs. Keying a second limit on the username closes that gap. Combined with
    `deduct_when` (only failed logins count), a legitimate user who signs in
    successfully is never throttled. Tradeoff: an attacker can still burn a
    victim's failure budget to cause a short, self-healing lockout window — an
    accepted cost of any account-scoped throttle. Falls back to the client IP
    when no username is supplied."""
    data = request.get_json(silent=True) or {}
    uname = (data.get("username") or "").strip().lower()
    return f"login-user:{uname}" if uname else get_remote_address()


@bp.route("/register", methods=["GET","POST"])
@limiter.limit("5 per hour", methods=["POST"])
def register():
    if request.method == "GET":
        return render_template("register.html", cognito_enabled=_cognito_available())
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    email = (data.get("email") or "").strip()
    password = data.get("password")

    if not username or not email or not password:
        return jsonify({"error" : "Tüm alanlar zorunludur"}), 400

    password_error = validate_password(password)
    if password_error:
        return jsonify({"error": password_error}), 400

    username_error = validate_username(username)
    if username_error:
        return jsonify({"error": username_error}), 400

    email_error = validate_email(email)
    if email_error:
        return jsonify({"error": email_error}), 400

    # Username/email collision. Return one generic message for both checks so the
    # response can't be used to confirm whether a specific username OR e-mail is
    # already registered (account-enumeration hardening). Combined with the per-IP
    # rate limit on this route, this raises the cost of enumeration. Note that
    # usernames are inherently discoverable via the friend search and there is no
    # e-mail login / reset flow, so the residual exposure is low.
    if (User.query.filter_by(username=username).first()
            or User.query.filter_by(email=email).first()):
        return jsonify({"error": "Bu kullanıcı adı veya e-posta zaten kullanımda."}), 400
    
    user = User(username = username , email = email)
    user.set_password(password)
    ensure_referral_code(user)
    db.session.add(user)
    db.session.commit()

    # Davet döngüsü: kayıt davet bağlantısından geldiyse (cookie veya body)
    # davetçi ile bağla ve iki tarafa da XP ver.
    ref_code = (data.get("ref") or request.cookies.get("fitx_ref") or "").strip()
    referred = bool(consume_referral(user, ref_code))

    resp = jsonify({"message": f"Hoş geldin {username}, hesabın oluşturuldu!",
                    "referred": referred})
    if request.cookies.get("fitx_ref"):
        resp.delete_cookie("fitx_ref")
    return resp


@bp.route("/login", methods=["GET","POST"])
@limiter.limit("10 per minute; 50 per hour", methods=["POST"])
@limiter.limit("15 per 15 minutes", key_func=_login_username_key, methods=["POST"],
               deduct_when=lambda response: response.status_code == 401)
def login():
    if request.method == "GET":
        auth_error = _AUTH_ERRORS.get(request.args.get("err", ""))
        return render_template("login.html", cognito_enabled=_cognito_available(),
                               auth_error=auth_error)
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")

    user = User.query.filter_by(username = username).first()

    # Always run one password hash comparison, whether or not the username
    # exists, so the response time can't reveal which usernames are registered.
    if user:
        password_ok = user.check_password(password or "")
    else:
        check_password_hash(_DUMMY_PW_HASH, password or "")
        password_ok = False

    if not password_ok:
        return jsonify({"error": "Kullanıcı adı veya şifre hatalı"}) , 401
    
    login_user(user)
    quest_result = complete_quest_for_user(user.id, "login")
    response = {"message": f"Hoş geldin {user.username}!"}
    if quest_result:
        response["quest_awarded"] = quest_result
    return jsonify(response)


@bp.route("/login/cognito")
def cognito_login():
    """Amazon Cognito Hosted UI'ya yönlendir (e-posta ile giriş/kayıt). Authlib
    server tarafında 302 üretir; durum (state) + PKCE verifier oturuma yazılır.
    Geri dönüş /auth/cognito/callback adresine olur — bu URL Cognito app client'ın
    izinli callback URL'leri arasında TANIMLI olmalı."""
    if not _cognito_available():
        abort(404)
    redirect_uri = url_for("auth.cognito_callback", _external=True)
    return oauth.oidc.authorize_redirect(redirect_uri)


@bp.route("/auth/cognito/callback")
def cognito_callback():
    """Cognito'dan dönüşü işle: token/userinfo al, yerel hesabı bul/oluştur, giriş
    yap. Bu bir GET top-level navigasyonudur (SameSite=Lax oturum çerezi gelir),
    state authlib tarafından doğrulanır → CSRF guard'ı POST'lara özgü olduğundan
    burada ek koruma gerekmez."""
    if not _cognito_available():
        abort(404)
    try:
        token = oauth.oidc.authorize_access_token()
    except Exception as e:
        current_app.logger.warning("[COGNITO] token değişimi başarısız: %s: %s",
                                   type(e).__name__, e)
        return redirect(url_for("auth.login", err="cognito"))

    userinfo = token.get("userinfo") or {}
    ref_code = (request.cookies.get("fitx_ref") or "").strip()
    try:
        user, _is_new = get_or_create_user(userinfo, ref_code=ref_code)
    except CognitoLinkError as e:
        current_app.logger.info("[COGNITO] hesap bağlama reddedildi: %s", e)
        return redirect(url_for("auth.login", err="link"))

    login_user(user)
    session["via_cognito"] = True  # /logout'un Cognito oturumunu da kapatması için
    complete_quest_for_user(user.id, "login")  # /login ile aynı yan etki
    resp = redirect(url_for("tracking.home"))  # eksik profil → home oradan setup'a yönlendirir
    if request.cookies.get("fitx_ref"):
        resp.delete_cookie("fitx_ref")
    return resp


@bp.route("/logout")
@login_required
def logout():
    # Logout CSRF guard. The logout links across the app are same-site <a>
    # navigations (GET), so this can't be POST-only without reworking every
    # template. Instead, reject cross-site triggers — e.g. an attacker page
    # embedding <img src="/logout"> to silently sign the user out. A genuine
    # same-site navigation reports Sec-Fetch-Site: same-origin/same-site/none;
    # for older browsers without that header we fall back to a Referer check.
    sec_site = request.headers.get("Sec-Fetch-Site")
    if sec_site:
        if sec_site not in ("same-origin", "same-site", "none"):
            abort(403, description="CSRF doğrulaması başarısız.")
    else:
        referer = request.headers.get("Referer")
        if referer:
            from urllib.parse import urlparse
            if urlparse(referer).hostname != request.host.split(":")[0]:
                abort(403, description="CSRF doğrulaması başarısız.")
    via_cognito = session.pop("via_cognito", False)
    logout_user()
    # Cognito ile girildiyse ve Hosted UI domain'i ayarlıysa Cognito oturumunu da
    # kapat — aksi halde "E-posta ile giriş" yeniden tıklanınca sessizce geri girer.
    # logout_uri, app client'ın "Allowed sign-out URLs" listesinde TANIMLI olmalı.
    if via_cognito and COGNITO_HOSTED_DOMAIN:
        from urllib.parse import urlencode
        params = urlencode({
            "client_id": COGNITO_APP_CLIENT_ID,
            "logout_uri": url_for("auth.login", _external=True),
        })
        return redirect(f"https://{COGNITO_HOSTED_DOMAIN}/logout?{params}")
    return redirect(url_for("auth.login"))
